#' Populate local search solutions
#' 
#' @description
#' The function populates solutions generated by the local search
#' algorithm [stblob_lsearch()] for a range of cluster numbers 
#' and relative spatial weights.
#' 
#' @inheritParams stblob_lsearch
#' @param k number of clusters. Either an integer or integer sequence.
#' @param w_space relative spatial weight of range \eqn{[0,1]}.
#' Either a numeric value or a vector of length 2.
#' The vector should specify the lower and upper bounds.
#' @param optim_type_diversity a logical value to optimise data type diversity.
#' Default is `FALSE`.
#' @param w_time relative spatial weight of range \eqn{[0,1]}. Default is `NULL`,
#' Supply a numeric value when fixed weights across runs are used.
#' @param w_time relative spatial weight of range \eqn{[0,1]}. Default is `NULL`,
#' Supply a numeric value when fixed weights across runs are used.
#' @param run number of runs per \eqn{k_i}. Default is `10L`.
#' @param batch number of batches. Default is `1L`.
#' @param parallel a logical value to parallelise the search. Default is `TRUE`.
#' @param workers number of parallel workers passed onto [future::plan()].
#' @param .batch internal argument for progress bar message. Default is NULL
#' Default is `NULL` with [future::availableCores()] ` - 1`.
#' @inheritDotParams stblob_lsearch
#' 
#' @details
#' The function is a wrapper of [stblob_lsearch()].
#' By sampling a range of parameter combinations of `w_space`, `w_time` and `w_type`,
#' it populates solutions that locally optimise trade-offs between spatial,
#' temporal and data type diversity cost functions with augmented weighted
#' Chebyshev (Tchebycheff) scalarisation (Steuer & Choo, 1983)
#' across \eqn{k} clusters.
#' Sampling is done via Latin hypercube sampling ([lhs::randomLHS()]) for a
#' single free parameter, otherwise from a Dirichlet distribution
#' with \eqn{\alpha = (1,1,1)} ([MCMCpack::rdirichlet()]).
#' If `w_space` is specified by a range of values, input values of
#' `w_time` and `w_type` will be ignored.
#' 
#' `outlier_removal` is being tested at the moment. The idea is to remove points
#' of which the distance to their medoid is an outlier based on the
#' interquantile range (IQR) of distances to medoid across \eqn{k} clusters.
#' 
#' @returns
#' an S3 object of class `pop` with the following components:
#'  * `clust`: a matrix of cluster assignments; row: solution;
#'  column: data point.
#'  * `summary`: a data frame of summary statistics. They include the parameter
#'  value of (`k`), number of clusters of the output (`k_o`), four
#'  objective values (`z_space`, `z_time1`, `z_time2` and `z_type`),
#'  number of iterations (`iter`), ARI with the previous iteration (`ari`),
#'  state of local search convergence (`ls_convergence`).
#'  `idx`, `run` and `batch` indicate the row in `clust`, run and batch from
#'  which it was generated. 
#'  and number of outliers (`n_outliers`).
#'  * `trace`: a data frame of summary statistics for each iteration.
#'  * `data`: a data frame of the input data.
#'  * `space_distmat`: a spatial distance matrix used for clustering.
#'  * `filter_summary`: a data frame of filter summary.
#'  * `adapt_search_params`: a list of parameter values for `adapt_search` in [stblob()].
#'  * `w_space_q3`: a data frame of upper quartiles (Q3) of `w_space` of solutions with intersecting boundaries.
#'  * `params`: a list of parameter values.
#' 
#' @seealso [compute_distmat()], [geosphere::distGeo()], [stblob_lsearch()],
#' [sf::st_as_sf()], [sf::st_concave_hull()],
#' [sf::sf_use_s2()], [aricode::ARI()], [future::future],
#' [future.apply::future.apply], [progressr::progressr]
#' 
#' @references
#' Steuer, R. E., & Choo, E.-U. (1983). An interactive weighted Tchebycheff
#' procedure for multiple objective programming. Mathematical Programming,
#' 26(3), 326–344.
#' 
#' @noRd

stblob_populate <- function(data,
                            k,
                            w_space,
                            optim_type_diversity = FALSE,
                            iter = 100L,
                            run = 100L,
                            batch = 1L,
                            w_time = NULL,
                            w_type = NULL,
                            
                            # additional input arguments like column names
                            coords = NULL,
                            age = NULL,
                            type = NULL,
                            space_distmat = NULL,
                            space_distmethod = c("geodesic", "euclidean"),
                            distGeo_a = 6378137,
                            distGeo_f = 1/298.257223563,
                            
                            # future.apply
                            parallel = TRUE,
                            workers = NULL,
                            .batch = NULL,
                            
                            # constraints and additional local search arguments
                            ...
                            ) {
  
  # record the essential param values
  params <- mget(ls(environment(), sorted = FALSE))
  # output as elements of output object
  params$data <- params$space_distmat <- NULL
  
  # check data
  check_args(data = data,
             optim_type_diversity = optim_type_diversity,
             iter = iter,
             coords = coords,
             age = age,
             type = type)
  
  # assign column names to NULL
  coords <- coords %||% names(data)[c(2,3)]
  age <- age %||% names(data)[4]
  type <- if (optim_type_diversity) type %||% names(data)[5] else NULL
  
  # check if space_distmat is supplied, compute space_distmat otherwise
  space_distmat <- check_space_distmat(data = data,
                                       coords = coords,
                                       space_distmat = space_distmat,
                                       space_distmethod = space_distmethod,
                                       distGeo_a = distGeo_a,
                                       distGeo_f = distGeo_f)
  
  # in case crs is not specified otherwise
  if (match.arg(space_distmethod, c("geodesic", "euclidean")) == "euclidean") hull_crs <- NA
  
  # check_opt_args
  check_opt_args(...)
  
  # check populate related args
  stopifnot(
    "'k' must be at least 2 and smaller than the number of samples" = all(k > 1L) & all(k < nrow(data)),
    "'run' must be at least 1" = run > 0L,
    "'batch' must be at least 1" =  batch > 0L,
    "'parallel' must be logical" = is.logical(parallel)
  )
  
  # parallel computing via future
  if (parallel) {
    oplan <- future::plan()                    
    on.exit(future::plan(oplan), add = TRUE)
    workers <- workers %||% (future::availableCores() - 1)
    future::plan(future::multisession, workers = workers)
  }
  
  # parameter combinations
  param_grid_list <- lapply(1:batch, function(i) {
    param_grid <- sample_param_grid(k = k,
                                    w_space = w_space,
                                    run = run,
                                    optim_type_diversity = optim_type_diversity,
                                    w_time = w_time,
                                    w_type = w_type)
    param_grid$batch <- i
    return(param_grid)
  })
  
  param_grid <- do.call(rbind, param_grid_list)

  # number of searches to perform
  NS <- nrow(param_grid)
  
  # param vectors
  grid_k <- param_grid$k
  grid_w_space <- param_grid$w_space
  grid_w_time <- param_grid$w_time
  grid_w_type <- param_grid$w_type
  grid_run <- param_grid$run
  grid_batch <- param_grid$batch
  
  # progress bar along the ncol of param_grid
  p <- progressr::progressor(along = 1:NS)

  sol_list <- future.apply::future_Map(function(k, w_space, w_time, w_type, run, batch, i) {
    # switch NA back to NULL
    if (is.na(w_type)) w_type <- NULL
    
    sol <- suppressMessages(
      stblob_lsearch(data = data,
                     k = k,
                     w_space = w_space, 
                     optim_type_diversity = optim_type_diversity,
                     w_time = w_time,
                     w_type = w_type,
                     iter = iter,
                     coords = coords, 
                     age = age, 
                     type = type, 
                     space_distmat = space_distmat,
                     space_distmethod = space_distmethod,
                     distGeo_a = distGeo_a,
                     distGeo_f = distGeo_f,
                     ...)
    )
    
    # data and space_distmat are redundant to process here
    sol$data <- NULL
    sol$space_distmat <- NULL
    
    if (sol$status == 0) {
      # label run and batch of the search
      sol$summary$run <- sol$trace$run <- run
      sol$summary$batch <- sol$trace$batch <- batch
    }
    
    sol <- unclass(sol)
    
    # progress
    if (!is.null(.batch)) {
      p(sprintf("batch = %g", .batch))
    } else {
      p(sprintf("lsearch = %g", i))
    } 
    
    return(sol)
  },
  grid_k, grid_w_space, grid_w_time, grid_w_type, grid_run, grid_batch, 1:NS,
  future.seed = TRUE)
  
  pop <- sol_to_pop(sol_list, data = data, space_distmat, params = params)
  return(pop)
}

# helpers ---------------------------------------------------------------------
## sample_param_grid ----------------------------------------------------------
sample_param_grid <- function(k,
                              w_space,
                              run,
                              optim_type_diversity,
                              w_time,
                              w_type) {
  # checks
  if (is.list(w_space)) {
    if (length(w_space) != 1) {
      stopifnot("'w_space' must be a list length equal to length of 'k'" =
                  length(w_space) == length(k))
    }
  } else {
    w_space <- list(w_space)
  }
  
  if (is.list(w_time)) {
    if (length(w_time) != 1) {
      stopifnot("'w_time' must be a list length equal to length of 'k'" =
                  length(w_time) == length(k))
      stopifnot("'w_time' must be a numeric value of length 1" =
                  all(vapply(w_time, length, numeric(1L)) == 1 | vapply(w_time, length, numeric(1L)) == 0))
    }
  } else {
    stopifnot("'w_time' must be a numeric value of length 1" =
                (is.numeric(w_time) && length(w_time) == 1) || length(w_time) == 0)
    w_time <- list(w_time)
  }
  
  if (is.list(w_type)) {
    if (length(w_type) != 1) {
      stopifnot("'w_type' must be a list length equal to length of 'k'" =
                  length(w_type) == length(k))
      stopifnot("'w_type' must be a numeric value of length 1" =
                  all(vapply(w_type, length, numeric(1L)) == 1 | vapply(w_type, length, numeric(1L)) == 0))
    }
  } else {
    stopifnot("'w_type' must be a numeric value of length 1" =
                (is.numeric(w_type) && length(w_type) == 1) || length(w_type) == 0)   
    w_type <- list(w_type)
  }
  
  # Map() cannot deal with NULL, NULL -> NA
  w_time <- lapply(w_time, function(x) x <- x %||% NA)
  w_type <- lapply(w_type, function(x) x <- x %||% NA)
  
  w_grid <- Map(function(x, y, z) {
    # switch NA back to NULL for sample_w()
    if (is.na(y)) y <- NULL
    if (is.na(z)) z <- NULL

    sample_w(w_space = x,
             run = run,
             optim_type_diversity = optim_type_diversity,
             w_time = y,
             w_type = z)},
    w_space, w_time, w_type)
  
  if (length(w_grid) != length(k)) w_grid <- rep(w_grid, length(k))
  
  param_grid <- Map(function(x, y) cbind(k = x, y), k, w_grid)
  param_grid <- do.call(rbind, param_grid)
  
  return(param_grid)
}

## sample_w -------------------------------------------------------------------
sample_w <- function(w_space,
                     run,
                     optim_type_diversity,
                     w_time,
                     w_type) {
  
  w <- NULL
  w_lens <- vapply(list(w_space, w_time, w_type), length, numeric(1L))
  
  stopifnot(
    "'w_space' must be between 0 and 1" =
      all(unlist(w_space) >= 0) && all(unlist(w_space) <= 1),
    "'w_time' must be between 0 and 1" =
      is.null(w_time) || (all(unlist(w_time) >= 0) && all(unlist(w_time) <= 1)),
    "'w_type' must be between 0 and 1" =
      is.null(w_type) || (all(unlist(w_type) >= 0) && all(unlist(w_type) <= 1))
  )
  
  if (!optim_type_diversity) {
    
    if (w_lens[1] == 2) {
      
      # Latin hypercube sampling
      lhs_samps <- lhs::randomLHS(run, 1)
      w1 <- sort(as.vector(min(w_space) + lhs_samps * (max(w_space) - min(w_space))))
      w2 <- 1 - w1
      
    } else {
      
      if (w_lens[1] == 1 && w_lens[2] == 1) {
        stopifnot("'w_space' and 'w_time' must sum up to 1" =
                    isTRUE(all.equal(sum(w_space, w_time), 1)))
      } else {
        w1 <- rep(w_space, run)
        w2 <- 1 - w1
      }
      
    }
    
    w <- data.frame(w_space = w1, w_time = w2, w_type = NA)
    
  } else {
    
    if (w_lens[1] == 1) {
      
      w1 <- rep(w_space, run)
      
      if (all(w_lens == 1)) {
        
        stopifnot("'w_space', 'w_time' and 'w_type' must sum up to 1" =
                    isTRUE(all.equal(sum(w_space, w_time, w_type), 1)))
        
        w2 <- rep(w_time, run)
        w3 <- rep(w_type, run)
        
      } 
      
      if (sum(w_lens == 1) == 2) {
        
        stopifnot("'w_space', 'w_time' and 'w_type' must sum up to 1" =
                    isTRUE(all.equal(sum(w_space, w_time, w_type), 1)) || sum(w_space, w_time, w_type) < 1)
        
        if (w_lens[2] == 1) {
          w2 <- rep(w_time, run)
          w3 <- 1 - w1 - w2
        }
        
        if (w_lens[3] == 1) {
          w3 <- rep(w_type, run)
          w2 <- 1 - w1 - w3
        }
        
      }
      
      if (sum(w_lens == 1) == 1) {
        
        if (w_space == 1) {
          w2 <- 1 - w1
          w3 <- 1 - w1
        }
        
        if (w_space < 1) {
          w_time <- c(1 - w_space, 0)
          # Latin hypercube sampling
          lhs_samps <- lhs::randomLHS(run, 1)
          w2 <- sort(as.vector(min(w_time) + lhs_samps * (max(w_time) - min(w_time))))
          w3 <- 1 - w1 - w2
        }
        
      }
      
      w <- data.frame(w_space = w1, w_time = w2, w_type = w3)
      if (any(abs(w) < .Machine$double.eps ^ 0.5)) w[abs(w) < .Machine$double.eps ^ 0.5] <- 0
    }
    
    # it got stuff here for some reason #### problem is it spit out 2 identical numbers after update which doesn't satisfy the sampling procedure
    if (w_lens[1] == 2) {
      w <- data.frame()
      while (nrow(w) < run) {
        dirchlet_samp <- MCMCpack::rdirichlet(1, c(1,1,1))
        # reject sample if w_space is outside the constraint
        if (dirchlet_samp[1] >= min(w_space) &
            dirchlet_samp[1] <= max(w_space)) {
          w <- rbind(w, dirchlet_samp)}
      }
      names(w) <- c("w_space", "w_time", "w_type")
    }
  }
  
  # index the run
  w$run <- 1:nrow(w)
  return(w)
}

## sol_to_pop -----------------------------------------------------------------
sol_to_pop <- function(sol_list, data, space_distmat, params) {
  # obtain full list of param values hidden in dots
  params_dots <- sol_list[[1]]$params[setdiff(names(sol_list[[1]]$params), names(params))]
  params <- c(params, params_dots)
  
  # summarise invalid runs
  invalid_idx <- which(vapply(sol_list, function(x) x$status > 0, logical(1L)))
  pop_summary <- summarise_pop(sol_list = sol_list, invalid_idx = invalid_idx)
  filter_summary <- pop_summary$filter_summary
  
  # combine output from valid runs
  runs <- 1:length(sol_list)
  runs_pass <- runs[!runs %in% invalid_idx]
  len_pass <- length(runs_pass)
  
  # rbind the list of output from different runs 
  if (len_pass > 0) {
    s <- sol_list[runs_pass]
    pop <- list()
    for (l in c("clust", "summary", "trace")) {
      # extract the df
      e <- lapply(s, function(x) x[[l]])
      if (l %in% c("summary", "trace")) {
        e <- Map(function(x,y) {
          x$idx <- y
          x <- x[c("idx", setdiff(names(x), "idx"))]
          return(x)
          }, e, 1:length(e))
      }
      e <- do.call(rbind, e)
      pop[[l]] <- e
    }
    
    clust <- pop$clust
    summary <- pop$summary
    trace <- pop$trace
    
    # find, label and remove the duplicates
    if (len_pass > 1) {
      dup <- duplicated(clust)
      # duplicated indices
      dup_idx <- which(dup)
      
      if (length(dup_idx) > 0) {
        # parameter k to split dup count
        dup_idx_k <- split(dup_idx, summary$k[dup_idx])
        
        # record the freq
        dup_counts <- vapply(dup_idx_k, function(x) length(x), integer(1L))
        dup_counts <- as.data.frame(dup_counts)
        dup_counts <- cbind(as.numeric(rownames(dup_counts)), dup_counts)
        names(dup_counts) <- c("k", "dup")
        
        # update filter_summary
        filter_summary <- merge(filter_summary, dup_counts, all.x = TRUE)
        filter_summary$dup[is.na(filter_summary$dup)] <- 0L
        filter_summary$pass <- filter_summary$pass - filter_summary$dup
        
        # remove the runs from the output
        clust <- unique(clust)
        summary <- subset(summary, !idx %in% dup_idx)
        trace <- subset(trace, !idx %in% dup_idx)
        # reindex the output
        rownames(summary) <- NULL
        summary$idx <- match(summary$idx, unique(summary$idx))
        rownames(trace) <- NULL
        trace$idx <- match(trace$idx, unique(trace$idx))
      } else {
        # no duplicates
        filter_summary$dup <- 0L
      }
    } else {
      # only one solution
      filter_summary$dup <- 0L
    }
  } else {
    clust <- summary <- trace <- NULL
    filter_summary$dup <- 0L
  }

  # reorder columns
  filter_summary <- filter_summary[c("k",
                                     "pass",
                                     "k1",
                                     "intersects",
                                     "clustsize",
                                     "intersects_clustsize",
                                     "dup")]
  
  # to be used in stblob()
  adapt_search_params <- list(k = pop_summary$k, w_space_q3 = pop_summary$w_space_q3)
  
  if (all(is.na(clust))) message("No feasible solution was found.")
  
  return(new_pop(clust = clust,
                 summary = summary,
                 trace = trace,
                 data = data,
                 space_distmat = space_distmat,
                 filter_summary = filter_summary,
                 adapt_search_params = adapt_search_params,
                 params = params))  
}

## summarise_pop --------------------------------------------------------------
summarise_pop <- function(sol_list, invalid_idx = NULL) {
  # sol_list: a list of sol objects or alike
  # invalid_idx: skip looking for status output from the list if supplied
  invalid_idx <- invalid_idx %||% which(vapply(sol_list, function(x) x$status > 0, logical(1L)))
  
  # k params for each sol
  k <- vapply(sol_list, function(x) x$params$k, numeric(1L))
  K <- as.integer(sort(unique(k)))
  
  status <- vapply(sol_list, function(x) x$status, numeric(1L))
  w_space <- vapply(sol_list, function(x) x$params$w_space, numeric(1L))
  # subset status intersect
  w_space[!(status == 2 | status == 4)] <- NA
  
  # status
  filter_summary <- lapply(split(status, k), function(x) {
    s <- integer(5L)
    x <- table(x)
    s[(as.numeric(names(x))+1)] <- x
    return(s)
  })
  
  filter_summary <- as.data.frame(do.call(rbind, filter_summary))
  # get column from rownames
  filter_summary <- cbind(as.integer(rownames(filter_summary)), filter_summary)
  # name the columns
  colnames(filter_summary) <- c("k", "pass", "k1", "intersects",
                                "clustsize", "intersects_clustsize")
  # obtain all k for the df
  filter_summary <- merge(data.frame(k = K), filter_summary, all.x = TRUE)
  filter_summary[is.na(filter_summary)] <- 0L
  
  # Q3 of w_space parameter values of solutions with intersects
  w_space_q3 <- lapply(
    split(w_space, k),
    function(x) as.numeric(stats::quantile(x, probs = 0.75, na.rm = TRUE))
  )
  w_space_q3 <- as.data.frame(do.call(rbind, w_space_q3))
  # get column from rownames
  w_space_q3 <- cbind(as.numeric(rownames(w_space_q3)), w_space_q3)
  # name the columns
  colnames(w_space_q3) <- c("k", "w_space_q3")
  # obtain all k for the df
  w_space_q3 <- merge(data.frame(k = K), w_space_q3, all.x = TRUE)
  
  # combine into filter_summary
  # filter_summary <- merge(status_counts, ws_q3)
  pop_summary <- list(k = K, filter_summary = filter_summary, w_space_q3 = w_space_q3)
  return(pop_summary)
}

## new_pop --------------------------------------------------------------------
new_pop <- function(clust, summary, trace, filter_summary, data, space_distmat, adapt_search_params, params) {
  stopifnot(is.matrix(clust) || is.numeric(clust) || is.null(clust) ,
            is.data.frame(summary) || is.null(summary),
            is.data.frame(trace) || is.null(trace),
            is.data.frame(filter_summary),
            is.data.frame(data),
            is.matrix(space_distmat),
            is.list(adapt_search_params),
            is.list(params))
  
  structure(
    list(clust = clust,
         summary = summary,
         trace = trace,
         filter_summary = filter_summary,
         data = data,
         space_distmat = space_distmat,
         
         adapt_search_params = adapt_search_params,
         params = params),
    class = "stblob_pop"
  )
}
